ogress{display:flex;justify-content:space-between;align-items:center;gap:12px}.source-navigation{justify-content:flex-end}.summary{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.summary div{padding:14px;background:#f7f8fb;border-radius:10px}.summary dt{color:var(--cb-text-muted,#667085);font-size:.85rem}.summary dd{font-weight:700;margin:5px 0 0}.review-summary{padding:14px;border:1px solid #e2e5ec;border-radius:10px}.review-summary summary{cursor:pointer;font-weight:700}.review-summary p{color:var(--cb-text-muted,#667085)}.review-summary ul{list-style:none;padding:0;display:grid;gap:8px}.review-summary li{display:flex;justify-content:space-between;gap:12px}.review-summary span{color:var(--cb-text-muted,#667085);text-align:right}.conflict-actions{justify-content:center;padding:12px}.sticky-action{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:12px 0;color:var(--cb-text-muted,#667085)}@media(max-width:600px){.import-wizard{padding:12px 12px 96px}.wizard-header{grid-template-columns:1fr auto}.wizard-header>.v-btn{grid-column:1/-1;justify-self:start}.wizard-card{padding:18px 16px}.summary{grid-template-columns:1fr}.wizard-card>.v-btn,.source-navigation>.v-btn,.inline-actions>.v-btn,.completion-actions>.v-btn,.publication-actions>.v-btn{width:100%;min-height:48px}.source-list li,.published-list li,.consolidation-list li,.source-resume-list li{grid-template-columns:auto 1fr}.source-list li>.v-btn,.published-list li>.v-btn,.source-resume-list li>.v-btn{grid-column:1/-1}.source-navigation,.inline-actions,.completion-actions,.publication-actions{flex-direction:column}.review-summary li{display:grid}.review-summary span{text-align:left}.sticky-action{position:fixed;left:0;right:0;bottom:0;background:white;border-top:1px solid #e7e9ef;padding:10px 12px calc(10px + env(safe-area-inset-bottom));z-index:5}.sticky-action span{font-size:.78rem;max-width:60%}}
